import { get } from 'lodash'
import { useRef, useEffect } from 'react'
import { DisplayCircleIcon, DisplayFlexRCC } from '../../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../../components'
import AmountTitle from '../../../../../../components/AmountTitle'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { PROOF_ID } from '../../../../../../constants/cookies'
import { removeFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { GOLD_TRANSACTION, NEW_SUCCESS_PROOF_IMG } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import { OVERPAYMENT_UNDER_PREMIUM } from '../../../constants'
import { OfflinePaymentStyle } from './index.style'

function OfflinePaymentConfirmContainer (props) {
  const { location, history } = props
  const isOverPayment = useRef((get(location, 'state.overPayment', 0) > 0))
  const isOverpaymentUnderPremium = useRef((get(location, 'state.scenario', '') === OVERPAYMENT_UNDER_PREMIUM))
  const handleToTransactionList = () => {
    history.push({
      pathname: '/transactions'
    })
  }

  useEffect(() => {
    removeFromLocalStorageData(PROOF_ID)
  }, [])

  return (
    <Container
      title={LANG_STRINGS.deliveryConfirmation}
      activeTab='transaction'
      className='bg-white'
      hideBackButton
    >
      <OfflinePaymentStyle>
        <DisplayFlexRCC>
          <DisplayCircleIcon
            width='190px'
            height='190px'
            bgColor={AgentColorPallette.fontLightGrey}
            className='photo-confirmation'
          >
            <img src={NEW_SUCCESS_PROOF_IMG} width='70%' height='auto' alt='' />
          </DisplayCircleIcon>
        </DisplayFlexRCC>
        <CustomText
          color={AgentColorPallette.black}
          size='15px'
          bottom='4px'
          top='10px'
          weight={800}
          textAlign='center'
        >
          {LANG_STRINGS.paymentOfPaymentSuccessful}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='14px'
          bottom='10px'
          textAlign='center'
        >
          {LANG_STRINGS.thankYouForYourTrust}
        </CustomText>
        {
          isOverPayment.current &&
          (
            <div className='over-payment-section'>
              <CustomText
                weight={700}
                size='10px'
                color={AgentColorPallette.regular}
              >
                {LANG_STRINGS.calculation}
              </CustomText>
              <AmountTitle
                title={isOverpaymentUnderPremium.current ? LANG_STRINGS.totalBill : LANG_STRINGS.mustPay}
                amount={get(location, 'state.totalBill', 0)}
                color={AgentColorPallette.fontDarkerGrey}
                size='10px'
                amountWeight={500}
                className='amount-section-border-top'
              />
              <AmountTitle
                title={isOverpaymentUnderPremium.current ? LANG_STRINGS.payment : LANG_STRINGS.paymentAmount}
                amount={get(location, 'state.amountPaid', 0)}
                color={AgentColorPallette.fontDarkerGrey}
                size='10px'
                amountWeight={500}
                className='amount-section-border-top'
              />
              {isOverpaymentUnderPremium.current &&
                <>
                  <CustomText
                    weight={700}
                    size='10px'
                    color={AgentColorPallette.regular}
                  >
                    {LANG_STRINGS.bonus}
                  </CustomText>

                  <AmountTitle
                    title={LANG_STRINGS.totalBonus}
                    amount={get(location, 'state.totalCommission', 0)}
                    color={AgentColorPallette.fontDarkerGrey}
                    size='10px'
                    amountWeight={500}
                    className='amount-section-border-top'
                  />

                  <AmountTitle
                    title={LANG_STRINGS.bonusUsed}
                    amount={get(location, 'state.commissionUsed', 0)}
                    color={AgentColorPallette.fontDarkerGrey}
                    size='10px'
                    amountWeight={500}
                    className='amount-section-border-top'
                  />

                  <AmountTitle
                    title={LANG_STRINGS.taxOnCommision}
                    amount={get(location, 'state.taxOnCommission', 0)}
                    color={AgentColorPallette.fontDarkerGrey}
                    size='10px'
                    amountWeight={500}
                    className='amount-section-border-top'
                  />
                </>}
              <AmountTitle
                title={isOverpaymentUnderPremium.current ? LANG_STRINGS.remainingBonus : LANG_STRINGS.difference}
                amount={isOverpaymentUnderPremium.current
                  ? get(location, 'state.commissionCreditedToWallet', 0)
                  : get(location, 'state.overPayment', 0)}
                color={AgentColorPallette.fontDarkerGrey}
                size='10px'
                amountWeight={500}
                className='amount-section-border-top'
              />

              <CustomText color={AgentColorPallette.black} size='14px' bottom='10px' top='10px'>
                {LANG_STRINGS.youHaveOverPaymentDifference}
              </CustomText>
              <CustomText color={AgentColorPallette.fontDarkerGrey} size='10px' bottom='20px'>
                {LANG_STRINGS.differenceIsTaxFree}
              </CustomText>
            </div>
          )
        }
        <div className='btn-container'>
          <ButtonWithIcon
            text={LANG_STRINGS.returnToTransactionList}
            icon={GOLD_TRANSACTION}
            className='icon-filter'
            iconRight
            onClick={handleToTransactionList}
          />
        </div>
      </OfflinePaymentStyle>
    </Container>
  )
}

export default OfflinePaymentConfirmContainer
